namespace GNProject.Views.sistemaPlanillas.RRHH
{
    public partial class FrmPlantillaContratoTrab : System.Web.UI.Page
    {
        protected void Page_Load(object sender, EventArgs e)
        {
            Page.UnobtrusiveValidationMode = System.Web.UI.UnobtrusiveValidationMode.None;
            return;
            //build the content for the dynamic Word document
            //in HTML alongwith some Office specific style properties.
            StringBuilder strBody = new StringBuilder("");

            strBody.Append("<html " + "xmlns:o='urn:schemas-microsoft-com:office:office' " +
        "xmlns:w='urn:schemas-microsoft-com:office:word'" +
        "xmlns='http://www.w3.org/TR/REC-html40'>" +
                    "<head><meta http-equiv='Content-Type' content='text-html;charset=utf-8'/><title>Time</title>");

            //The setting specifies document's view after it is downloaded as Print
            //instead of the default Web Layout
            strBody.Append("<!--[if gte mso 9]>" + "<xml>" + "<w:WordDocument>" + "<w:View>Print</w:View>" + "<w:Zoom>90</w:Zoom>" + "<w:DoNotOptimizeForBrowser/>" + "</w:WordDocument>" + "</xml>" + "<![endif]-->");

            strBody.Append("<style>" + "<!-- /* Style Definitions */" + "@page Section1" + "   {size:8.5in 11.0in; " + "   margin:1.0in 1.25in 1.0in 1.25in ; " + "   mso-header-margin:.5in; " + "   mso-footer-margin:.5in; mso-paper-source:0;}" + " div.Section1" + "   {page:Section1;}" + "-->" + "</style></head>");

            strBody.Append("<body lang=ES-PE style='tab-interval:.5in'>" +
                                        "<div style=\"text-align: center;\"><b><u><font face=\"verdana\" size=\"2\">[TIPO_RENOVACION] DE CONTRATO INDIVIDUAL DE TRABAJO POR NECESIDAD DE MERCADO</font></u></b></div><div><font face=\"verdana\" size=\"2\"><br></font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\">Conste por el presente documento, que se extiende por duplicado, EL CONTRATO INDIVIDUAL DE TRABAJO POR NECESIDAD DE MERCADO, según lo previsto en el artículo 58 del Texto Único Ordenado del D.L. Nº 728, Ley de Productividad y Competitividad Laboral, aprobado en D.S. Nº 003-97-TR, que celebran de una parte <b>LIMA GAS S.A.</b> con domicilio en Calle A Zona 7 Fundo Bocanegra Alto Callao - departamento de Lima, con Registro Único de Contribuyentes Nº 20100007348, debidamente representado por su Apoderado, Sr. Edgardo Javier, Zevallos Vasquez,, identificado con DNI. Nº 07589869, a quien en adelante se denominará EL EMPLEADOR; y de la otra parte el Sr(a). [NOMBRE_TRABAJADOR], Identificado con DNI Nº [DNI_TRABAJADOR], con domicilio en [DOMICILIO_TRABAJADOR], quien en lo sucesivo se denominará EL TRABAJADOR, en los términos y condiciones que constan en las cláusulas siguientes:&nbsp;</font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\"><br></font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\"><b>PRIMERA: EL EMPLEADOR</b> es una empresa que se dedica a las actividades de Envasado y comercialización de Gas Licuado de Petróleo (GLP), generado por la demanda temporal del mercado, la misma que varía de acuerdo a los requerimientos de la red de distribución y comercialización. Por esta razón, se necesita cubrir temporalmente las necesidades de recursos humanos originados por el crecimiento comercial temporal que conllevan, además al incremento temporal de actividades de operaciones, administración y control comercial de todas las áreas de gestión.</font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\">La necesidad de mercado se sustenta en el incremento temporal del 6% de la demanda comercial, proyectada para el proximo trimestre, lo cual conlleva a un incremento en las operaciones de ventas de GLP y su administración, debido a la demanda de 23 nuevos distribuidores Multimarca y de Red Sectorizada y de 14 clientes industriales que incrementan temporalmente la venta y la atención de requerimientos comerciales de GLP. Esta demanda comercial no puede ser cubierta por el personal permanente, pues lo que se requiere es atender esta necesidad temporal y coyuntural.&nbsp;</font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\"><br></font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\">SEGUNDA: En virtud del presente documento, EL EMPLEADOR contratará a plazo fijo bajo la modalidad indicada en el encabezamiento del presente contrato, los servicios de EL TRABAJADOR, para que se desempeñe como [CARGO_TRABAJADOR]. Siendo considerado un puesto sujeto a Fiscalización.</font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\"><br></font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\">TERCERA: Las labores que desarrollará EL TRABAJADOR tendrán una duración de labores que se contabilizarán desde el día 01 de noviembre del 2016 y concluirán el día 30 de noviembre del 2016.&nbsp;</font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\"><br></font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\">CUARTA: EL TRABAJADOR prestará servicios dentro de una jornada semanal de 48 horas. El horario de trabajo será variable y determinado por EL EMPLEADOR de acuerdo a sus necesidades.&nbsp;</font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\"><br></font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\">QUINTA: La remuneración básica mensual que percibirá EL TRABAJADOR, será de [SUELDO_TRABAJADOR_NUMERO] ([SUELDO_TRABAJADOR_LETRA]).&nbsp;</font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\"><br></font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\">SEXTA: Queda entendido que EL EMPLEADOR no está obligada a dar aviso alguno adicional referente al término del presente contrato, debido a su naturaleza temporal originado por las necesidades de mercado comerciales sustentadas en las Clausula Primera, operando su extinción a la expiración del tiempo convenido en la cláusula tercera, oportunidad en la cual se abonarán a EL TRABAJADOR los beneficios sociales que pudieran corresponderle de acuerdo a ley.&nbsp;</font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\"><br></font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\">SEPTIMA: EL TRABAJADOR se obliga durante y después de una posible resolución del contrato, a no proporcionar ni transferir directa o indirectamente a ninguna persona, empresa o entidad de cualquier índole, información confidencial o privilegiada relacionada con la actividad de EL EMPLEADOR, información institucional, secretos profesionales y cualquier otra información no conocida en el medio respeto de las actividades, las políticas y los proyectos, etc. Asimismo, EL TRABAJADOR se compromete y obliga a guardar absoluta reserva y confidencialidad acerca de todos los asuntos de LA EMPRESA, y de aquellas personas naturales o jurídicas que se relacionaron con ésta, directa o indirectamente. Especial compromiso, reserva y secreto profesional asume EL TRABAJADOR por todo aquello que se haya enterado o tomado conocimiento en atención a los cargos que haya desempeñado en LA EMPRESA, sea que esté relacionado o no con esta última, con los clientes y/o servicios prestados por LA EMPRESA.</font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\"><br></font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\">En consecuencia, toda información, conocimientos técnicos y procedimientos que LA EMPRESA haya suministrado a EL TRABAJADOR o que esta hubiera adquirido en el ejercicio de su cargo, se considerará para los efectos de este contrato, como Información Confidencial. Queda excluida toda información que se demuestre pertenecía ya al dominio público o que EL TRABAJADOR haya conocido antes que le fuera divulgada por LA EMPRESA. Además queda entendido que cualquier información profesional, comercial, laboral o técnica, preparada, recogida o desarrollada por EL TRABAJADOR durante la vigencia de la relación laboral, es considerada propiedad de LA EMPRESA, por lo que también quedarán sujetas a igual tratamiento de reserva y confidencialidad. Esta obligación de confidencial y reserva no cesará en momento alguno.&nbsp;</font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\"><br></font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\">EL TRABAJADOR que suscribe el presente contrato declara que estas obligaciones las asume libremente. Además, EL TRABAJADOR declara estar consciente de la responsabilidad civil que asume si por culpa o dolo contraviene las obligaciones señaladas en la presente cláusula, en perjuicio de LA EMPRESA, y estar en pleno conocimiento que de ello pueden derivarse incluso consecuencias penales, si divulgare la información confidencial obtenida durante el desempeño de sus labores.&nbsp;</font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\"><br></font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\">OCTAVA: EL TRABAJADOR estará sujeto al régimen laboral de la actividad privada, dentro de los alcances y efectos que determine la Ley de Productividad y Competitividad Laboral y demás normas complementarias y modificatorias para los trabajadores sujetos a contrato bajo modalidad.&nbsp;</font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\"><br></font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\">NOVENA: EL TRABAJADOR declara conocer el reglamento interno de trabajo, el reglamento de seguridad industrial y salud en el trabajo, prácticas y políticas específicas de EL EMPLEADOR y, por lo cual, se obliga a cumplir todo lo establecido en tales normas; asimismo, se compromete a prestar servicios con eficiencia, lealtad y sumo cuidado. Asimismo, de acuerdo a lo establecido en la Ley N° 29783, Ley de Seguridad y Salud en el Trabajo, se adjunta la descripción de las recomendaciones en Seguridad y Salud en el Trabajo.</font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\">Leer y practicar estrictamente el Reglamento de Seguridad y Salud en el Trabajo el cual fue recepcionado por EL TRABAJADOR</font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\">Respetar y aplicar las medidas de prevención de riesgos señalados en el Mapa de Riesgos ubicado en el acceso principal a las instalaciones.</font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\">Respetar y aplicar los estándares de seguridad establecidos en el puesto que desarrolla.</font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\">Aplicar las instrucciones impartidas en las capacitaciones dictadas por la empresa en materia de Seguridad y Salud en el Trabajo.</font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\">Colaborar con las investigaciones iniciadas por la empresa frente a daños en la salud de los trabajadores o indicios de que las medidas de prevención resultaron insuficientes.</font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\">Colaborar con la identificación de factores de riesgo en Seguridad y Salud en el Trabajo, debiendo ser estos comunicados a sus representantes inmediatamente hayan sido detectados.</font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\"><br></font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\">Esta relación no es limitativa sino enunciativa y se complementa con el anexo 1 y las normativas e instrucciones dictadas por los representantes del empleador en la ejecución del servicio así como en la descripción de funciones y actividades del puesto y por otros medios físicos, digitales y demás.&nbsp;</font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\"><br></font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\">La inobservancia y el incumplimiento de las normas de seguridad y salud en el trabajo indicadas en el presente documento, los reglamentos de seguridad y normativas expresas determinadas por EL EMPLEADOR, podrán generar Responsabilidad Penal en EL TRABAJADOR, de acuerdo a lo establecido en la Cuarta Disposición Complementaria Modificatoria de la Ley de Seguridad y Salud en el Trabajo, Ley N° 29783.</font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\"><br></font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\">DÉCIMA: Se establece que, en caso de surgir conflicto con relación a la interpretación, ejecución, término, nulidad, etc. Del presente convenio, las partes por medio de conversaciones bilaterales directas tratarán de llegar a un acuerdo dentro del más franco espíritu de colaboración y comprensión mutua.&nbsp;</font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\"><br></font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\">Si lo indicado en el párrafo precedente no fuera posible, las partes acuerdan que cualquier desavenencia, controversia o reclamación que pudiera derivarse de este contrato o de cualquier otra relación entre las partes, incluidas las de su nulidad o invalidez, serán resueltas, única y exclusivamente, mediante un arbitraje de derecho, de conformidad con lo previsto en el artículo 104 de la Ley Procesal de Trabajo, Ley Nº 26636; Ley General de Arbitraje, Ley Nº 26572; y demás normas complementarias y conexas.</font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\"><br></font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\">Para tales efectos, se constituirán un Tribunal Arbitral en la ciudad de Lima formado por tres árbitros: cada parte nombrará a un árbitro y los árbitros así designados nombrarán al tercero quien presidirá el tribunal arbitral, cada parte asumirá el costo de sus árbitros y deberá pagar a prorrata el honorario del presidente del Tribunal Arbitral.&nbsp;</font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\"><br></font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\">DÉCIMA PRIMERA: Las partes ratifican que el presente contrato constituye un acto jurídico válido que no se encuentra afectado por causal de invalidez o ineficacia alguna y se presentará al Ministerio de Trabajo y Promoción Social dentro de los primeros quince días de celebrado.&nbsp;</font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\"><br></font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\">Firmado por duplicado, en señal de conformidad y aprobación el día 31 de octubre del 2016.</font></div><div style=\"text-align: justify;\"><font face=\"verdana\" size=\"2\"><br></font></div><div><font face=\"verdana\" size=\"2\"><br></font></div><div><font face=\"verdana\" size=\"2\"><br></font></div><div><font face=\"verdana\" size=\"2\"><br></font></div><div><font face=\"verdana\" size=\"2\"><br></font></div><div><font face=\"verdana\" size=\"2\"><br></font></div><div style=\"text-align: center;\"><font face=\"verdana\" size=\"2\">............................... &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;.................................</font></div><div style=\"text-align: center;\"><font face=\"verdana\" size=\"2\">EL EMPLEADOR &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;EL TRABAJADOR</font></div>"
                                         + "</body></html>");

            //Force this content to be downloaded
            //as a Word document with the name of your choice
            Response.Clear();
            Response.AppendHeader("Content-Type", "application/msword");
            Response.AppendHeader("Content-disposition", "attachment; filename=myword.doc");
            Response.Write(strBody);
            Response.End();
        }
        [WebMethod]
        public static object Get_Inicial()
        {
            return controllerContratosPlantilla.getinstance().Get_Inicial();
        }
