        public static object Get_Bandeja(String[] strParametros)
        {
            return controllerContratosPlantilla.getinstance().Get_Bandeja(strParametros);
        }
        [WebMethod]
        public static object GuardarPlantilla(String[] strParametros)
        {
            return controllerContratosPlantilla.getinstance().GuardarPlantilla(strParametros);
        }
    }
